package com.ecommerce.commerceapi.products.api; import com.ecommerce.commerceapi.products.service.ProductService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/products") public class ProductController {private final ProductService service; public ProductController(ProductService service){this.service=service;} @GetMapping public List<ProductResponse> all(){return service.findAll();} @GetMapping("/{id}") public ProductResponse one(@PathVariable Long id){return service.findById(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ProductResponse create(@Valid @RequestBody ProductRequest request){return service.create(request);}@PutMapping("/{id}") public ProductResponse update(@PathVariable Long id,@Valid @RequestBody ProductRequest request){return service.update(id,request);}@PatchMapping("/{id}/status") public ProductResponse status(@PathVariable Long id,@Valid @RequestBody ProductStatusRequest request){return service.updateStatus(id,request.status());}}
